FUNCTION_BLOCK FB
VAR_OUTPUT
    leadPump : INT := 0;
    lagPump : INT := 0;
    runningCount : INT := 0;
END_VAR
VAR_INPUT
    demand : INT;
    runHours : ARRAY[1..5] OF LINT;
    rotated : BOOL;
END_VAR
VAR
    prevLeadPump : INT := 0;
    prevLagPump : INT := 0;
    prevRunningCount : INT := 0;
    tmpLead : INT;
    tmpLag : INT;
    tmpCount : INT;
    minHours : LINT;
    minPump : INT;
    i : INT;
END_VAR
VAR_TEMP
    local_i : INT;
